const DK2_MATS=Object.keys(DK2_MDEF);
for(const m of DK2_MATS){if(GA.idx[m]==null){GA_MATS.push(m);GA.idx[m]=GA_MATS.length-1}}
function paintDk2Atlas(){const PS=GA.P,cv=GA.canvas;if(!cv)return;const x=cv.getContext('2d');
  const patch=(name,fn,alpha)=>{const i=GA.idx[name];if(i==null||i>=GA_SLOTS)return;const x0=(i%8)*PS,y0=Math.floor(i/8)*PS,id=x.getImageData(x0,y0,PS,PS),D=id.data;
    for(let y=0;y<PS;y++)for(let xx=0;xx<PS;xx++){const c=fn(xx,y,x0+xx,y0+y);if(!c)continue;const k=(y*PS+xx)*4,r=rgbOf(c);D[k]=r[0];D[k+1]=r[1];D[k+2]=r[2];D[k+3]=alpha||255}
    x.putImageData(id,x0,y0)};
  const nz=(X,Y,s,c)=>fbm(X/(c||16),Y/(c||16),s,2,0);
  // scratches: short light strokes at a slant, as many as the sheet's scratch asks
  const scr=(xx,y,s,k)=>k>0&&hash2(Math.floor((xx+y*.4)/3),Math.floor(y/7),s)<k*.06;
  const tone=(c,t)=>t<.5?mix(c[0],c[1],clamp(t*2,0,1)):mix(c[1],c[2],clamp(t*2-1,0,1));
  const PAT={
    // fine streaks over a slow cloud, a soft band of sheen
    brushed:(c,s,k)=>(xx,y,X,Y)=>{const t=.5+(hash2(Math.floor(xx/24)+s,y,s)-.5)*.32+(nz(X,Y,s+1,22)-.5)*.75,b=Math.max(0,1-Math.abs(((y+xx*.3)%64)-32)/10);
      let o=mix(tone(c,t),c[2],b*.3);if(scr(xx,y,s+2,k))o=lt(c[2],.15);return o},
    // a soft mottle in the three tones
    noise:(c,s,k)=>(xx,y,X,Y)=>{const t=nz(X,Y,s,12)+(hash2(X,Y,s+1)-.5)*.1;let o=t>.6?c[2]:t<.4?c[0]:c[1];if(scr(xx,y,s+2,k))o=lt(c[2],.08);return o},
    // a light (alpha 232: it keeps its colour in the dark), the three tones in a slow swirl
    glow:(c,s)=>(xx,y,X,Y)=>{const t=nz(X,Y,s,10);return t>.62?c[2]:t<.38?c[0]:c[1]}};
  // alpha: 232 a light; gloss .3 and up a sheen on the world model, 248..254 (lower would light itself in the view model); under it matte
  DK2_MATS.forEach((m,i)=>{const [c,p,gl,k]=DK2_MDEF[m];patch(m,PAT[p](c,1801+i*10,k),p==='glow'?232:gl>=.3?Math.min(254,Math.max(248,Math.round(239+15*gl))):255)});
  GA.tex.needsUpdate=true;GA.texVM.needsUpdate=true;for(const k in ICONS)delete ICONS[k]}
{const pc=paintCgAtlas;paintCgAtlas=function(){pc();paintDk2Atlas()}}

